"""Pack the raw linear RGBA atlas generated by generate-msdf.cpp into the lazy TS module."""
import base64
import gzip
import pathlib
import sys
raw = pathlib.Path(sys.argv[1]).read_bytes()
assert len(raw) == 384 * 144 * 4
encoded = base64.b64encode(gzip.compress(raw, mtime=0)).decode()
pathlib.Path('src/gpu/ui/atlas-data.ts').write_text(
    '// Generated by scripts/ui/generate-msdf.cpp; Anton (OFL), msdfgen 1c106ed.\n'
    f"export const ATLAS_GZIP = '{encoded}';\n"
)
